B:  Postal Code

  S のA+1 文字目がハイフンであり、それ以外の全ての文字が0 以上9 以下である場合に‘Yes‘、
そうでない場合に‘No‘ を出力するとよいです。

#include <cstdio >
int A,B;
char s[12];
int main ()
{
         scanf ("%d%d",&A,&B);
         scanf ("%s",&s);
        for(int i=0;i<A;i++)if(!(’0’<=s[i]&&s[i]<=’9’))
          {
                 puts ("No"); return 0;
          }
        if(s[A]!=’-’)
          {
                 puts ("No"); return 0;
          }
        for(int i=A+1;i<=A+B;i++)if(!(’0’<=s[i]&&s[i]<=’9’))
          {
                 puts ("No"); return 0;
          }
         puts ("Yes ");
}



